package dev.unbox.client;

import net.minecraft.client.Minecraft;
import net.minecraft.client.Screenshot;
import net.minecraft.client.gui.components.AbstractWidget;
import net.minecraft.client.gui.components.EditBox;
import net.minecraft.client.input.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;

/** Explicit opt-in regression driver. Only run against an isolated copied test world. */
public final class VisualV4SmokeTest {
 private static net.minecraft.world.phys.Vec3 bodyBefore;private static float bodyYaw;private static net.minecraft.client.CameraType cameraBefore;
 private static int step;private static long at,skinSequence;private static net.minecraft.world.entity.player.PlayerSkin originalSkin;private static final List<String> checks=new ArrayList<>();
 private static void check(boolean ok,String text){if(!ok)throw new IllegalStateException(text);checks.add(text);}
 private static MouseButtonEvent event(double x,double y){return new MouseButtonEvent(x,y,new MouseButtonInfo(0,0));}
 private static AbstractWidget find(Minecraft m,String label){return m.screen.children().stream().filter(c->c instanceof AbstractWidget w&&w.visible&&w.getMessage().getString().equals(label)).map(c->(AbstractWidget)c).findFirst().orElseThrow(()->new IllegalStateException("Missing "+label));}
 private static void click(Minecraft m,String label){var w=find(m,label);float scale=m.screen instanceof UnboxHomeScreen s?s.menuScale():m.screen instanceof UnboxScreen s?s.menuScale():1;float offset=m.screen instanceof UnboxHomeScreen s?s.menuOffsetY():m.screen instanceof UnboxScreen s?s.menuOffsetY():0;var e=event((w.getX()+w.getWidth()/2.)*scale,(w.getY()+w.getHeight()/2.+offset)*scale);check(m.screen.mouseClicked(e,false),"Click "+label);m.screen.mouseReleased(e);}
 private static void shot(Minecraft m,String name){Screenshot.grab(m.gameDirectory,"v4-"+name+".png",m.getMainRenderTarget(),1,c->{});}
 private static String hex(byte[] bytes)throws Exception{var out=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(bytes))out.append(String.format("%02x",b));return out.toString();}
 private static void skinFixture(Minecraft m,String uuid,boolean damaged)throws Exception{Path root=m.gameDirectory.toPath(),png=root.resolve("unbox-local-skin.png");if(damaged)Files.write(png,new byte[]{1,2,3,4,5});else{try(var image=new com.mojang.blaze3d.platform.NativeImage(64,64,false)){image.fillRect(0,0,64,64,0xff3f75d6);image.fillRect(8,8,8,8,0xfff2c19d);image.writeToFile(png);}}byte[] bytes=Files.readAllBytes(png);var active=new com.google.gson.JsonObject();active.addProperty("id","visual-smoke-fixture");active.addProperty("sha256",hex(bytes));active.addProperty("model","classic");var manifest=new com.google.gson.JsonObject();manifest.addProperty("sequence",++skinSequence);manifest.addProperty("accountUuid",uuid);manifest.addProperty("accountName",m.getUser().getName());manifest.add("active",active);Files.writeString(root.resolve("unbox-skin-library.json"),new com.google.gson.Gson().toJson(manifest));}
 private static boolean wickEnabled()throws Exception{Class<?> client=Class.forName("dev.wick.client.WickClient");Object config=client.getMethod("config").invoke(null);return (boolean)config.getClass().getMethod("enabled").invoke(config);}
 private static void setWick(boolean enabled)throws Exception{Class<?> client=Class.forName("dev.wick.client.WickClient");Object config=client.getMethod("config").invoke(null);config.getClass().getMethod("setEnabled",boolean.class).invoke(config,enabled);}
 public static void tick(Minecraft m){
  if(!Boolean.getBoolean("unbox.visualSmoke")||m.player==null)return;
  m.getFramerateLimitTracker().onInputReceived();long now=System.currentTimeMillis();if(at==0)at=now;if(now-at<(step==0?5000:1000))return;at=now;
  try{switch(step++){
   case 0->{m.setScreen(new UnboxHomeScreen(true));check(PanelStyle.hudWidth("123 FPS")==m.font.width("123 FPS"),"HUD uses native pixel font metrics");}
   case 1->{shot(m,"quick-menu");var s=(UnboxHomeScreen)m.screen;var field=UnboxHomeScreen.class.getDeclaredField("skinPreview");field.setAccessible(true);var preview=(PlayerPreview)field.get(s);float playerYaw=m.player.getYRot(),playerBody=m.player.yBodyRot;
    var center=preview.extractState(m.player,90,118,90,118,false);float centerBody=center.bodyRot;
    var left=preview.extractState(m.player,90,118,10,78,false);float leftBody=left.bodyRot,leftHead=left.yRot;
    check(leftBody>centerBody&&leftHead>0&&left.xRot<0,"Preview body and head follow the mouse left/up like the native inventory");
    var right=preview.extractState(m.player,90,118,170,158,false);float rightBody=right.bodyRot,rightHead=right.yRot;
    check(rightBody<centerBody&&rightHead<0&&right.xRot>0,"Preview body and head follow the mouse right/down like the native inventory");
    preview.rotate(60);var dragged=preview.extractState(m.player,90,118,10,78,true);
    check(Math.abs(dragged.bodyRot-(rightBody-60))<.01&&dragged.yRot==rightHead,"Dragging right rotates the preview right without competing mouse follow");
    preview.rotate(-120);var reverse=preview.extractState(m.player,90,118,90,118,true);
    check(Math.abs(reverse.bodyRot-(rightBody+60))<.01,"Dragging left reverses the preview rotation");
    check(m.player.getYRot()==playerYaw&&m.player.yBodyRot==playerBody,"Preview rendering never changes the real player's body rotation");}
   case 2->{shot(m,"skin-rotated");click(m,"Change skin");check(m.screen instanceof SkinLibraryScreen,"Quick menu opens skin library");}
   case 3->{check(!find(m,"Redeem").active,"Unverified game identity cannot redeem codes");check(find(m,"Unbox")!=null,"Skin library includes the basic Unbox logo");shot(m,"skin-library");m.screen.onClose();click(m,"MODS");var card=find(m,"Minimap");check(card.getWidth()==card.getHeight()+30,"Module body and integrated state strip form a square");}
   case 4->{shot(m,"cards");for(var c:m.screen.children())if(c instanceof EditBox box&&box.getMessage().getString().equals("Search mods")){box.setValue("Nickname");break;}click(m,"Nickname");}
   case 5->{var box=(EditBox)find(m,"Local nickname");box.setValue("Builder");click(m,"Apply");check(LocalNickname.get().equals("Builder"),"Nickname saves for the current UUID");UnboxClient.set("nickname",true);var original=net.minecraft.network.chat.Component.literal("Real name");check(LocalNickname.render(m.player.getUUID(),original).getString().equals("Builder"),"Own rendered nickname changes");check(LocalNickname.render(UUID.randomUUID(),original).getString().equals("Real name"),"Other players retain their names");}
   case 6->{shot(m,"nickname");m.setScreen(null);NameplateSmokeTest.verify(m,checks);UnboxClient.set("scoreboard",true);UnboxClient.set("scoreboard.backgroundColor","#112244");UnboxClient.set("scoreboard.opacity",65);UnboxClient.set("scoreboard.titleOpacity",80);m.getSingleplayerServer().execute(()->{var server=m.getSingleplayerServer();var source=server.createCommandSourceStack();server.getCommands().performPrefixedCommand(source,"scoreboard objectives add v4 dummy Survival");server.getCommands().performPrefixedCommand(source,"scoreboard objectives setdisplay sidebar v4");server.getCommands().performPrefixedCommand(source,"scoreboard players set Builds v4 12");});}
   case 7->{shot(m,"own-nameplate");NameplateSmokeTest.restore(m);shot(m,"scoreboard-live");check((ScoreboardAppearance.background(false)&0xffffff)==0x112244,"Scoreboard reads selected background color");UnboxClient.set("scoreboard.showScores",false);}
   case 8->{shot(m,"scoreboard-hidden-scores");m.setScreen(new UnboxHomeScreen(true));m.options.guiScale().set(6);m.resizeGui();}
   case 9->{shot(m,"quick-gui6");click(m,"MODS");}
   case 10->{shot(m,"cards-gui6");click(m,"Close");m.options.guiScale().set(2);m.resizeGui();m.setScreen(new FriendsScreen(new UnboxHomeScreen(true)));}
   case 11->{shot(m,"friends");m.setScreen(null);originalSkin=m.player.getSkin();skinSequence=System.currentTimeMillis();skinFixture(m,m.getUser().getProfileId().toString(),false);}
   case 12->{check(m.player.getSkin().body().id().equals(net.minecraft.resources.Identifier.fromNamespaceAndPath("unbox","local_skin")),"Generated local skin replaces the current player's texture");m.setScreen(new UnboxHomeScreen(true));}
   case 13->{shot(m,"local-skin-preview");skinFixture(m,UUID.randomUUID().toString(),false);}
   case 14->{check(m.player.getSkin().body().id().equals(originalSkin.body().id()),"A skin manifest for another UUID restores the original texture");skinFixture(m,m.getUser().getProfileId().toString(),true);}
   case 15->{check(m.player.getSkin().body().id().equals(originalSkin.body().id()),"A damaged local skin cannot replace the original texture");setWick(true);UnboxClient.set("dynamiclight",false);DynamicLightsBridge.sync();}
   case 16->{check(!wickEnabled(),"Unbox disables Wick through its live config bridge");m.setScreen(null);UnboxClient.set("dynamiclight",true);m.getSingleplayerServer().execute(()->{var player=m.getSingleplayerServer().getPlayerList().getPlayer(m.getUser().getProfileId());player.setItemSlot(net.minecraft.world.entity.EquipmentSlot.MAINHAND,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.TORCH));});}
   case 17->{check(wickEnabled(),"Unbox enables Wick through its live config bridge");int sources=(int)Class.forName("dev.wick.client.LightTracker").getMethod("sources").invoke(null);check(sources>0,"A held torch registers a real dynamic light source");int light=(int)Class.forName("dev.wick.core.Lights").getMethod("packedAt",int.class,int.class,int.class).invoke(null,m.player.getBlockX(),m.player.getBlockY()+1,m.player.getBlockZ());check(light>0,"Wick provides nonzero light around the player's held torch");}
   case 18->{shot(m,"lights-enabled");UnboxClient.set("dynamiclight",false);}
   case 19->{shot(m,"lights-disabled");check((int)Class.forName("dev.wick.client.LightTracker").getMethod("sources").invoke(null)==0,"Disabling dynamic lights removes active light sources");}
   case 20->{UnboxClient.set("freecam",true);bodyBefore=m.player.position();bodyYaw=m.player.getYRot();cameraBefore=m.options.getCameraType();m.setScreen(new UnboxScreen());((EditBox)find(m,"Search mods")).setValue("Freecam");click(m,"Freecam");click(m,"Change keybind");m.screen.keyPressed(new KeyEvent(org.lwjgl.glfw.GLFW.GLFW_KEY_F7,0,0));check(FreecamController.key().matches(new KeyEvent(org.lwjgl.glfw.GLFW.GLFW_KEY_F7,0,0)),"Freecam settings UI saves an F7 key binding");m.setScreen(null);net.minecraft.client.KeyMapping.click(com.mojang.blaze3d.platform.InputConstants.Type.KEYSYM.getOrCreate(org.lwjgl.glfw.GLFW.GLFW_KEY_F7));}
   case 21->{check(FreecamController.active(),"Saved F7 binding activates the real detached camera");check(m.getCameraEntity()!=m.player&&m.getCameraEntity().isSpectator(),"Freecam uses a distinct native spectator camera so the body remains renderable");FreecamIntegrationChecks.verify(m,checks);Freelook.activate(true);FreecamController.tick(m);m.options.keyUp.setDown(true);m.player.turn(40,30);check(!Freelook.active(),"Freecam suspends the conflicting Freelook runtime without changing its configuration");check(m.player.getYRot()==bodyYaw,"Freecam mouse input leaves body rotation unchanged");}
   case 22->{double cameraDelta=FreecamController.position().distanceTo(bodyBefore),bodyDelta=m.player.position().distanceTo(bodyBefore);var input=m.player.input.getMoveVector();check(cameraDelta>2,"Movement input moves the detached camera [delta="+cameraDelta+"]");check(input.lengthSquared()<1.0E-6,"Freecam clears both key state and computed movement vector [input="+input+"]");check(bodyDelta<.1,"Camera movement does not move the player body [delta="+bodyDelta+", velocity="+m.player.getDeltaMovement()+", onGround="+m.player.onGround()+"]");m.options.keyUp.setDown(false);var toward=m.player.getEyePosition().subtract(FreecamController.position());float targetYaw=(float)Math.toDegrees(Math.atan2(-toward.x,toward.z)),targetPitch=(float)-Math.toDegrees(Math.atan2(toward.y,Math.hypot(toward.x,toward.z)));FreecamController.turn((targetYaw-FreecamController.yaw())/.15,(targetPitch-FreecamController.pitch())/.15);}
   case 23->{var rendered=m.gameRenderer.getMainCamera();check(rendered.entity()==FreecamController.cameraEntity(),"Rendered main camera is bound to the spectator entity");check(rendered.position().distanceTo(FreecamController.position())<1.1,"Rendered camera follows the interpolated spectator position [rendered="+rendered.position()+", controller="+FreecamController.position()+"]");check(Math.abs(net.minecraft.util.Mth.wrapDegrees(rendered.yaw()-FreecamController.yaw()))<1,"Rendered camera uses the spectator yaw [actual="+rendered.yaw()+", target="+FreecamController.yaw()+", entityView="+FreecamController.cameraEntity().getViewYRot(1)+"]");check(Math.abs(rendered.xRot()-FreecamController.pitch())<1,"Rendered camera uses the spectator pitch [actual="+rendered.xRot()+", target="+FreecamController.pitch()+"]");shot(m,"freecam-body");check(m.getCameraEntity()!=m.player,"Detached camera remains active while capturing the player body");net.minecraft.client.KeyMapping.click(com.mojang.blaze3d.platform.InputConstants.Type.KEYSYM.getOrCreate(org.lwjgl.glfw.GLFW.GLFW_KEY_F7));}
   case 24->{check(!FreecamController.active(),"Saved F7 binding exits Freecam");check(m.getCameraEntity()==m.player&&m.options.getCameraType()==cameraBefore,"Freecam restores the original camera entity and perspective");m.setScreen(new RedeemScreen(new SkinLibraryScreen(new UnboxHomeScreen(true))));}
   case 25->{shot(m,"redeem-local-disabled");check(!find(m,"Redeem").active,"Local redemption form refuses submission");var box=(EditBox)find(m,"Redemption code");box.setValue("ABCD1-ABCD2-ABCD3-ABCD4-ABCD5-ABCD6-ABCD7-ABCD8");check(box.getValue().length()==47,"Game redemption field accepts a complete code");m.screen.onClose();check(m.screen instanceof SkinLibraryScreen,"Closing redemption returns to the skin library");Files.writeString(m.gameDirectory.toPath().resolve("logs/visual-smoke.json"),new com.google.gson.Gson().toJson(Map.of("passed",checks.size(),"checks",checks)));m.stop();}

  }}catch(Exception e){throw new RuntimeException("Unbox visual v4 regression at "+(step-1),e);}
 }
}
